// AxISA v2.0 step 3 (see sw/hadrons_test.axasm and docs/ISA.md's
// "Quark flavor and hadrons"): BARYON QN / MESON QN on 8 baryons and 6
// mesons plus 7 illegal combinations. GENERATED by
// tools/gen_hadrons_test.py - expected words come from its PDG table.
`timescale 1ns/1ps
`ifndef INSTR_HEX
`define INSTR_HEX "sw/hadrons_test.hex"
`endif

module tb_hadrons;
    reg clk, reset;
    integer errors;
    integer max_cycles;
    integer cycle_count;

    wire halted;
    wire [31:0] tohost_value;
    wire        bus_req, bus_mem_write, bus_mem_unsigned, bus_grant;
    wire [31:0] bus_addr, bus_write_data, bus_read_data;
    wire [1:0]  bus_mem_size;
    wire        uart_tx_valid;
    wire [7:0]  uart_tx_data;

    cpu_core #(.INSTR_MEM_WORDS(1024), .INSTR_INIT_FILE(`INSTR_HEX)) dut (
        .clk(clk), .reset(reset), .halted(halted), .tohost_value(tohost_value),
        .irq_in(1'b0),
        .bus_req(bus_req), .bus_addr(bus_addr), .bus_write_data(bus_write_data),
        .bus_mem_write(bus_mem_write), .bus_mem_size(bus_mem_size), .bus_mem_unsigned(bus_mem_unsigned),
        .bus_grant(1'b0), .bus_read_data(32'b0),
        .uart_tx_valid(uart_tx_valid), .uart_tx_data(uart_tx_data),
        .uart_rx_data_in(8'b0), .uart_rx_ready_in(1'b0), .uart_rx_ack()
    );

    always #5 clk = ~clk;

    task check(input [31:0] got, input [31:0] expected, input [48*8-1:0] name);
        begin
            if (got !== expected) begin
                $display("FAIL: %0s got=%0d (0x%h) expected=%0d (0x%h)", name, got, got, expected, expected);
                errors = errors + 1;
            end else begin
                $display("PASS: %0s = %0d (0x%h)", name, got, got);
            end
        end
    endtask

    initial begin
        errors = 0;
        max_cycles = 600;

        clk = 0;
        reset = 1;
        cycle_count = 0;
        @(posedge clk); @(posedge clk);
        reset = 0;

        while (!halted && cycle_count < max_cycles) begin
            @(posedge clk);
            cycle_count = cycle_count + 1;
        end

        if (!halted) begin
            $display("FAIL: core never halted within %0d cycles", max_cycles);
            errors = errors + 1;
        end else begin
            $display("Halted after %0d cycles. tohost=%0d", cycle_count, tohost_value);
            check(tohost_value, 32'd9, "tohost (n7 = traps taken)");
            check(dut.n_bank.regs[6], 32'd0, "n6 (sum of trap causes, 0 = ILLEGAL)");
            check(dut.n_bank.regs[4], 32'd55, "n4 (sentinel: no illegal hadron wrote)");
            check(dut.dmem.mem[11'h100], 32'h01000011, "proton uud");
            check(dut.dmem.mem[11'h101], 32'h0F000010, "neutron udd");
            check(dut.dmem.mem[11'h102], 32'h03000012, "Delta++ uuu");
            check(dut.dmem.mem[11'h103], 32'h00000D1F, "Omega- sss");
            check(dut.dmem.mem[11'h104], 32'h00000F10, "Lambda uds");
            check(dut.dmem.mem[11'h105], 32'h00001011, "Lambda_c+ udc");
            check(dut.dmem.mem[11'h106], 32'h000F0010, "Lambda_b udb");
            check(dut.dmem.mem[11'h107], 32'h0F0000FF, "antiproton");
            check(dut.dmem.mem[11'h108], 32'h02000001, "pi+ u dbar");
            check(dut.dmem.mem[11'h109], 32'h0E00000F, "pi- d ubar");
            check(dut.dmem.mem[11'h10A], 32'h01000101, "K+ sbar u");
            check(dut.dmem.mem[11'h10B], 32'h00000000, "J/psi c cbar");
            check(dut.dmem.mem[11'h10C], 32'h01010001, "B+ u bbar");
            check(dut.dmem.mem[11'h10D], 32'h0F001000, "D0 c ubar");
            check(dut.dmem.mem[11'h10E], 32'h00000000, "end-marker slot stays 0");
        end

        if (errors == 0) $display("ALL AXISA HADRONS TESTS PASSED");
        else $display("%0d AXISA HADRONS TEST(S) FAILED", errors);
        $finish;
    end
endmodule
